#include <bits/stdc++.h>
using namespace std;
using ll=long long;
int main() {
	// your code goes here
int t;
cin>>t;

while(t--)
{
    int n;
    cin>>n;
    
    vector<ll>a(3*n);
    for(auto &x:a) cin>>x;
    
    sort(a.rbegin(),a.rend());
    
    vector<ll>pre(3*n+1,0);
    for(int i=0;i<3*n;i++)
    {
        pre[i+1]=pre[i]+a[i];
        }
        
        ll ans=0;
        
        for(int x=0;x<=n;x++)
        {
            int maxb=n-x;
            
            auto calc=[&](int b)-> ll{
                int j=x+2*b;
                int k=3*n-2*x-b;
                return 2*pre[x]+pre[j]+3*pre[k];
            };
            
            int lo=0,hi=maxb;
            
            while(lo<hi)
            {
                int mid=(lo+hi)/2;
                
                ll delta=a[x+2*mid]+a[x+2*mid+1]-3*a[3*n-2*x-mid-1];
                
                if(delta<=0)
                 hi=mid;
                else
                 lo=mid+1;
            }
            
            ans=max(ans,calc(lo));
            
            if(lo>0)
            {
                ans=max(ans,calc(lo-1));
            }
        }
    cout<<ans<<endl;
}
return 0;
}
